import re, sys, os, json
ROOT = sys.argv[1]
APPLY = len(sys.argv) > 2 and sys.argv[2] == "apply"
PILL_TAGS = {"app-pill", "app-fancy-pill", "app-status-pill"}
KEEP_TAGS = {"app-card", "app-pill-legacy"}
OCC = re.compile(r"\bdisableTooltip\b")
TAGSTART = re.compile(r"<([A-Za-z][\w-]*)")

def tag_info(text, i):
    """Return (tagname, inQuote) if position i is inside an open tag, else None."""
    j = text.rfind("<", 0, i)
    while j >= 0:
        m = TAGSTART.match(text, j)
        if m:
            break
        # a '<' not starting a tag: keep searching only if it's a '<' inside non-tag text
        return None
    else:
        return None
    if m is None:
        return None
    k = m.end()
    q = None
    while k < i:
        c = text[k]
        if q:
            if c == q:
                q = None
        elif c in "\"'":
            q = c
        elif c == ">":
            return None
        k += 1
    return (m.group(1), q is not None)

results = []
for dp, dn, fn in os.walk(ROOT):
    if "node_modules" in dp or "\\.angular" in dp or "/.angular" in dp:
        continue
    for f in fn:
        if not f.endswith((".ts", ".html", ".css")):
            continue
        p = os.path.join(dp, f)
        text = open(p, encoding="utf-8").read()
        for m in OCC.finditer(text):
            i = m.start()
            line = text.count("\n", 0, i) + 1
            ti = tag_info(text, i) if not p.endswith(".css") else None
            before = text[max(0, i-1):i]
            after = text[m.end():m.end()+1]
            if p.endswith(".css"):
                kind = "css"
                ctx = text[text.rfind("\n", 0, i)+1: text.find("\n", i)]
                ctx_tag = re.findall(r"([\w-]+)\[disableTooltip\]", ctx)
                action = "rename" if all(t in PILL_TAGS for t in ctx_tag) and ctx_tag else "keep"
            elif ti and not ti[1]:
                tag = ti[0]
                kind = "attr-of-" + tag
                action = "rename" if tag in PILL_TAGS else ("keep" if tag in KEEP_TAGS else "REVIEW")
            elif ti and ti[1]:
                kind = "value-in-" + ti[0]
                action = "REVIEW"
            else:
                kind = "nontag"
                action = "REVIEW"
            results.append((p, line, kind, action, text[text.rfind("\n",0,i)+1:text.find("\n",i)].strip()[:150], i, m.end()))

import collections
c = collections.Counter((r[2], r[3]) for r in results)
for k, v in sorted(c.items()):
    print(v, k)
print("---- REVIEW items:")
for r in results:
    if r[3] == "REVIEW":
        print(f"{os.path.relpath(r[0], ROOT)}:{r[1]} [{r[2]}] {r[4]}")
json.dump([(r[0], r[5], r[6], r[3]) for r in results], open(os.path.join(os.path.dirname(__file__), "plan.json"), "w"))
EOF
